  const names=next?[...(next.towers||[]).map(k=>game.roster[k]?.name||k),...(next.maps||[]).map(m=>MAPS[m]?.name||m),...(next.modes||[]).map(m=>({endless:"Endless Siege",onslaught:"Onslaught"})[m]||m)]:[];
