 function checkUnlocks(){const s=game.state;if(s.waveHistory.length===seenWaves)return;const cleared=s.waveHistory.slice(seenWaves).map(w=>w.wave);seenWaves=s.waveHistory.length;const xp0=profile.xp,ups=progress.gainXp(profile,cleared,s.mode),gained=profile.xp-xp0;if(gained>0){runXp+=gained;xpPop(gained);}for(const u of ups)for(const k of u.towers||[])game.command({type:"unlock",kind:k});if(ups.length){const top=ups.at(-1),opened=ups.flatMap(u=>[...(u.towers||[]).map(k=>game.roster[k].name),...(u.maps||[]).map(m=>MAPS[m].name),...(u.modes||[]).map(m=>({endless:"Endless Siege",onslaught:"Onslaught"})[m])]);setTimeout(()=>{banner("Level "+top.level+"!",opened.length?"Unlocked: "+opened.join(", "):"","win");notice("Level "+top.level+"! "+(opened.length?"Unlocked: "+opened.join(", ")+".":""),true);$("hudLevel").classList.add("leveled");setTimeout(()=>$("hudLevel").classList.remove("leveled"),2600);},900);sfx.play("star");}const fresh=progress.recordRun(profile,{wave:s.waveHistory.at(-1).wave,mode:s.mode,fallen:s.stats.fallen,returns:s.stats.returns,sacrifices:s.stats.sacrifices,won:s.phase==="won",colors:Object.values(s.towers).map(t=>game.roster[t.kind].color)});progress.save(storage,profile);if(fresh.length)notice("New commander unlocked: "+fresh.map(id=>game.commanders[id].name).join(", ")+". Choose them before wave 1 of your next run.");}
