 canvas.addEventListener("click",e=>{const {x,y}=coords(e);if(selectedCard!==null&&game.cards[game.state.hand[selectedCard]]?.target==="ground"){cast(selectedCard,{x,y});return;}if(moving){if(commanderAt(x,y)){cancelMove();return;}if(!onRoad(x,y)){cancelMove();if(selected!==null)selectPad(null);return;}moving=false;if(game.command({type:"commanderMove",x,y})){const q=game.pointAt(game.nearestPath(x,y));moveMark={x:q.x,y:q.y,at:performance.now()};movedOnce=true;sfx.play("click");$("notice").classList.remove("show");}else notice("Commander unavailable.");renderHud();return;}if(!rallying&&commanderAt(x,y)){selectCommander();return;}if(!rallying){if(selected!==null)selectPad(null);return;}if(game.command({type:"rally",pad:selected,x,y})){rallying=false;notice("Rally point moved.");}else notice("Choose a road position within the tower’s range.");renderHud();});
